    static function help() {
        echo ('<section data-oc-panel="help" class="oc-admin-card"><h2>'.esc_html(Orthocal_I18n::text('Помощь')).'</h2><p>'.esc_html(Orthocal_I18n::text('Подключение хранит доступ к источникам и локальный кэш. Обычные блоки календаря работают без регистрации и API-ключа; ключ нужен только для расширенного доступа. Внешний вид, размер, картинки, содержание дня и поведение относятся к конкретному блоку и задаются в конструкторе.')).'</p><h3>'.esc_html(Orthocal_I18n::text('Как работать')).'</h3><ol><li>'.esc_html(Orthocal_I18n::text('При необходимости введите дополнительный ключ календаря во вкладке «Подключение».')).'</li><li>'.esc_html(Orthocal_I18n::text('Откройте «Конструктор», выберите вид блока и настройте его слева.')).'</li><li>'.esc_html(Orthocal_I18n::text('Проверьте живой результат справа и скопируйте строку в блок WordPress «Шорткод».')).'</li></ol><h3>'.esc_html(Orthocal_I18n::text('Стандартные шорткоды')).'</h3><p>'.esc_html(Orthocal_I18n::text('Их можно вставить напрямую в блок «Шорткод», без конструктора:')).'</p><pre class="oc-shortcode-list">'.esc_html(Orthocal_I18n::text('[orthocal_today] — карточка сегодняшнего дня
[orthocal_upcoming limit="5" filter="main"] — ближайшие праздники
[orthocal_month year="2027" month="5"] — календарь на месяц
[orthocal_year year="2027"] — календарь на год
[orthocal_day date="2027-05-02"] — карточка выбранной даты
[orthocal_readings date="2027-05-02"] — библейские чтения дня
[orthocal_calendar] — общий календарь
[orthocal_fasting] — пост и трапеза
[orthocal_saints] — памяти святых
[orthocal_feasts limit="5"] — список праздников
[orthocal_memorial] — поминальные дни
[orthocal_pascha year="2027"] — дата Пасхи и сведения о ней
[orthocal_fasts year="2027"] — посты года
[orthocal_date] — дата по новому и старому стилю
[orthocal_texts] — библиотека богослужебных текстов
[orthocal_troparia] — тропари
[orthocal_kontakia] — кондаки
[orthocal_prayers] — молитвы
[orthocal_magnifications] — величания
[orthocal_horologion] — полный справочник Часослова')).'</pre><details><summary>'.esc_html(Orthocal_I18n::text('Почему компактный блок выглядит иначе?')).'</summary><p>'.esc_html(Orthocal_I18n::text('Он предназначен для боковой колонки: уменьшает ячейки и скрывает длинные подписи сетки.')).'</p></details><details><summary>'.esc_html(Orthocal_I18n::text('Почему не загружается перевод Библии?')).'</summary><p>'.esc_html(Orthocal_I18n::text('Каталог приходит из BibleDesktop. Плагин покажет точную ошибку подключения; календарные данные от этого не останавливаются.')).'</p></details><details><summary>'.esc_html(Orthocal_I18n::text('Что означают иконы?')).'</summary><p>'.esc_html(Orthocal_I18n::text('Показываются все иконы, которые календарный API передаёт для выбранной даты.')).'</p></details></section>');
    }
